-- =========================================================
-- MINDCARE STUDENT - DATABASE SEED
-- Dataset sintetis untuk simulasi akademik (bukan data nyata)
-- Login akun dummy: password = password
-- Disarankan mengganti password setelah instalasi.
-- =========================================================

CREATE DATABASE IF NOT EXISTS db_mindcare
  CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE db_mindcare;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS rekomendasi;
DROP TABLE IF EXISTS detail_hasil_spk;
DROP TABLE IF EXISTS hasil_spk;
DROP TABLE IF EXISTS jawaban;
DROP TABLE IF EXISTS pengisian;
DROP TABLE IF EXISTS pertanyaan;
DROP TABLE IF EXISTS kriteria;
DROP TABLE IF EXISTS mahasiswa;
DROP TABLE IF EXISTS users;
SET FOREIGN_KEY_CHECKS = 1;

CREATE TABLE users (
    id INT AUTO_INCREMENT PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    role ENUM('admin','mahasiswa') NOT NULL DEFAULT 'mahasiswa',
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB;

CREATE TABLE mahasiswa (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL UNIQUE,
    nim VARCHAR(20) NOT NULL UNIQUE,
    nama VARCHAR(100) NOT NULL,
    prodi VARCHAR(100) NOT NULL,
    angkatan YEAR NOT NULL,
    jenis_kelamin ENUM('L','P') NOT NULL,
    email VARCHAR(120) NOT NULL UNIQUE,
    FOREIGN KEY (user_id) REFERENCES users(id)
        ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE kriteria (
    id INT AUTO_INCREMENT PRIMARY KEY,
    kode VARCHAR(5) NOT NULL UNIQUE,
    nama_kriteria VARCHAR(100) NOT NULL,
    bobot DECIMAL(5,4) NOT NULL,
    jenis ENUM('benefit','cost') NOT NULL DEFAULT 'benefit',
    keterangan VARCHAR(255)
) ENGINE=InnoDB;

CREATE TABLE pertanyaan (
    id INT AUTO_INCREMENT PRIMARY KEY,
    kriteria_id INT NOT NULL,
    pertanyaan TEXT NOT NULL,
    urutan TINYINT NOT NULL,
    aktif TINYINT(1) NOT NULL DEFAULT 1,
    FOREIGN KEY (kriteria_id) REFERENCES kriteria(id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    UNIQUE KEY uq_pertanyaan_urutan (kriteria_id, urutan)
) ENGINE=InnoDB;

CREATE TABLE pengisian (
    id INT AUTO_INCREMENT PRIMARY KEY,
    mahasiswa_id INT NOT NULL,
    tanggal DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    status ENUM('draft','selesai') NOT NULL DEFAULT 'selesai',
    FOREIGN KEY (mahasiswa_id) REFERENCES mahasiswa(id)
        ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;

CREATE TABLE jawaban (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    pengisian_id INT NOT NULL,
    pertanyaan_id INT NOT NULL,
    nilai TINYINT NOT NULL,
    FOREIGN KEY (pengisian_id) REFERENCES pengisian(id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY (pertanyaan_id) REFERENCES pertanyaan(id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    UNIQUE KEY uq_jawaban (pengisian_id, pertanyaan_id),
    CHECK (nilai BETWEEN 1 AND 5)
) ENGINE=InnoDB;

CREATE TABLE hasil_spk (
    id INT AUTO_INCREMENT PRIMARY KEY,
    pengisian_id INT NOT NULL UNIQUE,
    nilai_akhir DECIMAL(10,6) NOT NULL,
    kategori VARCHAR(40) NOT NULL,
    tanggal_hitung DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (pengisian_id) REFERENCES pengisian(id)
        ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;

-- Menyimpan rincian normalisasi dan kontribusi tiap kriteria.
CREATE TABLE detail_hasil_spk (
    id INT AUTO_INCREMENT PRIMARY KEY,
    hasil_id INT NOT NULL,
    kriteria_id INT NOT NULL,
    nilai_kriteria DECIMAL(8,4) NOT NULL,
    nilai_normalisasi DECIMAL(10,6) NOT NULL,
    bobot DECIMAL(5,4) NOT NULL,
    kontribusi DECIMAL(10,6) NOT NULL,
    FOREIGN KEY (hasil_id) REFERENCES hasil_spk(id)
        ON UPDATE CASCADE ON DELETE CASCADE,
    FOREIGN KEY (kriteria_id) REFERENCES kriteria(id)
        ON UPDATE CASCADE ON DELETE RESTRICT,
    UNIQUE KEY uq_detail_hasil (hasil_id, kriteria_id)
) ENGINE=InnoDB;

CREATE TABLE rekomendasi (
    id INT AUTO_INCREMENT PRIMARY KEY,
    hasil_id INT NOT NULL UNIQUE,
    deskripsi TEXT NOT NULL,
    FOREIGN KEY (hasil_id) REFERENCES hasil_spk(id)
        ON UPDATE CASCADE ON DELETE CASCADE
) ENGINE=InnoDB;

