INSERT INTO kriteria (kode, nama_kriteria, bobot, jenis, keterangan) VALUES
('C1', 'Stres akademik', 0.2500, 'benefit', 'Skor tinggi menunjukkan lebih sering mengalami tekanan akademik.'),
('C2', 'Kesulitan tidur', 0.2000, 'benefit', 'Skor tinggi menunjukkan lebih sering mengalami kesulitan tidur.'),
('C3', 'Kesulitan emosional', 0.2500, 'benefit', 'Skor tinggi menunjukkan lebih sering mengalami kesulitan mengelola emosi.'),
('C4', 'Keterbatasan dukungan sosial', 0.1500, 'benefit', 'Skor tinggi menunjukkan lebih sering merasa kurang mendapat dukungan.'),
('C5', 'Ketidakseimbangan aktivitas', 0.1500, 'benefit', 'Skor tinggi menunjukkan lebih sering kesulitan menjaga keseimbangan aktivitas.');

INSERT INTO pertanyaan (kriteria_id, pertanyaan, urutan) VALUES
(1, 'Saya merasa kewalahan dengan tugas atau tuntutan akademik.', 1),
(1, 'Saya merasa sulit mengatur waktu untuk menyelesaikan kegiatan kuliah.', 2),
(1, 'Saya merasa tertekan ketika memikirkan nilai atau hasil akademik.', 3),
(2, 'Saya mengalami kesulitan untuk mulai tidur.', 1),
(2, 'Saya terbangun pada malam hari dan sulit tidur kembali.', 2),
(2, 'Saya merasa waktu tidur saya tidak cukup untuk beristirahat.', 3),
(3, 'Saya merasa sulit menenangkan diri ketika menghadapi masalah.', 1),
(3, 'Saya merasa suasana hati saya mengganggu kegiatan sehari-hari.', 2),
(3, 'Saya merasa sulit berkonsentrasi karena pikiran atau perasaan yang mengganggu.', 3),
(4, 'Saya merasa tidak memiliki orang yang bisa diajak berbicara saat menghadapi kesulitan.', 1),
(4, 'Saya merasa kurang mendapat dukungan dari lingkungan sekitar.', 2),
(4, 'Saya merasa kesulitan meminta bantuan ketika membutuhkannya.', 3),
(5, 'Saya merasa kesulitan membagi waktu antara kuliah, istirahat, dan kegiatan pribadi.', 1),
(5, 'Saya sering mengabaikan waktu istirahat karena kegiatan lain.', 2),
(5, 'Saya merasa kegiatan sehari-hari tidak memiliki keseimbangan yang baik.', 3);

