-- Pemeriksaan jumlah data setelah import:
SELECT 'users' AS tabel, COUNT(*) AS jumlah FROM users
UNION ALL SELECT 'mahasiswa', COUNT(*) FROM mahasiswa
UNION ALL SELECT 'kriteria', COUNT(*) FROM kriteria
UNION ALL SELECT 'pertanyaan', COUNT(*) FROM pertanyaan
UNION ALL SELECT 'pengisian', COUNT(*) FROM pengisian
UNION ALL SELECT 'jawaban', COUNT(*) FROM jawaban
UNION ALL SELECT 'hasil_spk', COUNT(*) FROM hasil_spk
UNION ALL SELECT 'detail_hasil_spk', COUNT(*) FROM detail_hasil_spk
UNION ALL SELECT 'rekomendasi', COUNT(*) FROM rekomendasi;

-- Contoh melihat kontribusi SAW untuk pengisian pertama:
SELECT
    k.kode,
    k.nama_kriteria,
    d.nilai_kriteria,
    d.nilai_normalisasi,
    CONCAT(ROUND(d.bobot * 100, 2), '%') AS bobot_persen,
    d.kontribusi
FROM detail_hasil_spk d
JOIN kriteria k ON k.id = d.kriteria_id
WHERE d.hasil_id = 1
ORDER BY k.id;
